def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    player_count = 1 + len(alive)
    approx_winners = max(1, int(supply // WATER_REQ))
    scarcity = player_count - approx_winners

    prev_bids = []
    desperate_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp += 1

    my_desperate = (hp <= 2) or (no_water >= 2)

    if not alive:
        return min(budget, 20)

    base = 24
    if scarcity >= 2:
        base = 40
    elif scarcity == 1:
        base = 32

    if my_desperate:
        base = max(base, 58)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 46)

    if desperate_opp >= 2 and not my_desperate:
        base = min(base, 28)
    elif desperate_opp >= 1 and not my_desperate and scarcity <= 1:
        base = min(base, 30)

    if prev_bids:
        highest_prev = max(prev_bids)
        if my_desperate:
            bid = max(base, highest_prev + 2)
        elif scarcity >= 2:
            bid = max(base, highest_prev + 1)
        else:
            if highest_prev >= 60:
                bid = min(base, 26)
            else:
                bid = max(base, highest_prev + 1)
                bid = min(bid, 49)
    else:
        bid = base

    if budget < bid:
        bid = budget

    if hp >= 7 and scarcity <= 0 and not my_desperate:
        bid = min(bid, 22)

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # No competition: minimal bid to get water if needed
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    # Extract yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Estimate opponent budgets today (budget after yesterday + daily salary)
    # We only have yesterday's budget_after; use it to gauge if they can bid high
    # We will base our bid on yesterday's max bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0

    # Determine our bid based on health and opponent's previous aggression
    if my_status['hp'] <= 2:
        # Need water badly, outbid highest previous if possible
        target_bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 5)
        return min(my_status['budget'], target_bid)
    else:
        # Conservative: bid half salary, but not more than needed to beat previous
        base_bid = DAILY_SALARY * 0.4
        if highest_prev_bid > base_bid:
            # Outbid slightly to win if necessary
            target_bid = highest_prev_bid + 2
        else:
            target_bid = base_bid
        return min(my_status['budget'], target_bid)
